n/// text with an offset is read too.\nfn instant(text: String) -> Maybe<Instant> {\n    case OffsetDateTime.parse(String.replace(text, \" \", \"T\")) {\n        Ok(odt) ->\n            Some(OffsetDateTime.to_instant(odt))\n\n        Err(_) ->\n            NaiveDateTime.parse(text)\n            |> Result.to_maybe()\n            |> Maybe.flat_map(fn naive -> {\n                OffsetDateTime.with_offset(naive, Duration.hours(0)) |> Result.to_maybe()\n            })\n            |> Maybe.map(OffsetDateTime.to_instant)\n    }\n}\n",
